ruleToc.chapterList:
$..[?(@.type=='audio'||@.type=='text')]
@js:
let raw = result;
let arr = JSON.parse(raw);          // 先解析成数组
arr.filter(it => it.type === 'audio' ) // it.type === 'text'文本
 .map(it => ({
        title: it.title,
        url: it.mediaStreamUrl,
        download: it.mediaDownloadUrl
    }))
